package app.zhijian.notes;
import app.zhijian.notes.data.NoteQueries;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class NoteQueriesTest {
 private JSONObject n(String id,String title,long created,long updated,boolean pinned)throws Exception{return new JSONObject().put("id",id).put("title",title).put("createdAt",created).put("updatedAt",updated).put("pinned",pinned).put("mode","markdown").put("plainText","一 二\n三");}
 @Test public void firstLineNeverJoinsParagraphsOrSplitsEmoji(){assertEquals("第一行",NoteQueries.firstLine("\n  \n 第一行 \r\n第二行"));assertEquals("",NoteQueries.firstLine(" \n"));String text="😀".repeat(200);String result=NoteQueries.firstLine(text);assertEquals(160,result.codePointCount(0,result.length()));assertFalse(Character.isHighSurrogate(result.charAt(result.length()-1)));}
 @Test public void sortingKeepsPinnedFirstAndChangesUnpinnedOrder()throws Exception{JSONArray a=new JSONArray().put(n("b","Beta",100,400,false)).put(n("p","Pin",200,200,true)).put(n("a","Alpha",300,300,false));assertEquals("p",NoteQueries.sorted(a,"title").getJSONObject(0).getString("id"));assertEquals("a",NoteQueries.sorted(a,"title").getJSONObject(1).getString("id"));assertEquals("b",NoteQueries.sorted(a,"updated").getJSONObject(1).getString("id"));assertEquals("a",NoteQueries.sorted(a,"created").getJSONObject(1).getString("id"));assertEquals("b",NoteQueries.sorted(a,"oldest").getJSONObject(1).getString("id"));}
 @Test public void dateRangeIsHalfOpenAndModeFilteringIsExact()throws Exception{JSONObject n=n("a","A",200,300,false);assertTrue(NoteQueries.matches(n,new JSONObject().put("from",200).put("to",201).put("mode","markdown")));assertFalse(NoteQueries.matches(n,new JSONObject().put("to",200)));assertFalse(NoteQueries.matches(n,new JSONObject().put("mode","rich")));}
 @Test public void overviewCountsCreationDaysAndProducesExistingRandomId()throws Exception{JSONArray a=new JSONArray().put(n("a","A",1700000000000L,200,false)).put(n("b","B",1700000000000L,300,false).put("favorite",true));JSONObject s=NoteQueries.overview(a);assertEquals(2,s.getInt("total"));assertEquals(1,s.getInt("days"));assertEquals(1,s.getInt("favorites"));assertEquals(6,s.getInt("words"));assertTrue(s.getString("randomId").equals("a")||s.getString("randomId").equals("b"));assertTrue(NoteQueries.overview(new JSONArray()).isNull("randomId"));}
}
